ee:message.ee:set-payload:
%dw 2.0
output application/json
var cycle = read(payload,"aplication/xml")
var error = cycle.replies.reply.response.@result == 'E'
---
if (not error)
{
  "response": {
    "operation": cycle.replies.reply.response.@operation,
    "result": cycle.replies.reply.response.@result,
    "system": cycle.replies.reply.response.@system,
    "faults":  cycle.replies.reply.response.faults
  }
}
else
{
  "response": {
    "operation": cycle.replies.reply.response.@operation,
    "result": cycle.replies.reply.response.@result,
    "system": cycle.replies.reply.response.@system,
    "faults":  {
        "fault": {
            "fault_detail": cycle.replies.reply.response.faults.fault.fault_detail.@
        }
    }
  }
}

%dw 2.0
output application/json
var error = payload.response.@result == 'E'
---
if (not error){
InvokeServiceProvisioningOutput: {
    WSResponseHeader2: {
        System: {
            name: vars.nameHeader,
            correlationID: vars.correlationHeader,
            processingServer: vars.sourceHeader
        },
        Service: {
            status: "PASS",
            responseDate: now()
        }
    },
    BodyResponse: {
        response: {
   		 	"operation": payload.response.@operation,
    		"result": payload.response.@result,
    		"system": payload.response.@system,
    		"services":  payload.response.services
  		}
    }
  }
}
else
{
	"status": 500,
	"code": "ERROR_REVCHAIN",
	"message": {
		"message": {
			"error_code": payload.response.faults.fault_detail.@error_code,
			"error_description": payload.response.faults.fault_detail.@error_description
		}
	},
	"messageServer": "",
	"cause": [
		{
			"origin": "revchain-sapi-services",
			"message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
		}
	]
}

%dw 2.0
output application/json
---
if(isEmpty(payload))
{
  "status": 404,
  "code": "NOT_FOUND",
  "message": {
    "message": "No se encontraron datos en Revchain"
  },
  "messageServer": "No se encontraron datos en Revchain",
  "cause": [
    {
      "origin": "revchain-sapi-services",
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}
else payload

%dw 2.0
output application/json
---
if(isEmpty(payload))
{
  "status": 404,
  "code": "NOT_FOUND",
  "message": {
    "message": "No se encontraron datos en Revchain"
  },
  "messageServer": "No se encontraron datos en Revchain",
  "cause": [
    {
      "origin": "revchain-sapi-services",
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}
else payload
